// Generates zod schemas from the JSON Schema sources:
//   packages/schemas/json/*.schema.json   (config files)
//   config/formats/<format>/schema.json   (draft submits)
// Run with `pnpm --filter @anr/schemas gen`. Never edit src/generated by hand.
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { dereference } from "@apidevtools/json-schema-ref-parser";
import { jsonSchemaToZod } from "json-schema-to-zod";

const root = new URL("..", import.meta.url).pathname;
const formatsDir = join(root, "../../config/formats");
const outDir = join(root, "src/generated");

const toName = (s: string) =>
  s.replace(/(^|[-.])([a-z])/g, (_m, _sep: string, c: string) => c.toUpperCase()) + "Schema";

const sources: { name: string; file: string }[] = [
  ...readdirSync(join(root, "json"))
    .filter((f) => f.endsWith(".schema.json"))
    .map((f) => ({ name: toName(f.replace(".schema.json", "")), file: join(root, "json", f) })),
  ...readdirSync(formatsDir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith("_"))
    .map((d) => ({
      name: toName(`${d.name}-draft`),
      file: join(formatsDir, d.name, "schema.json"),
    })),
].sort((a, b) => a.name.localeCompare(b.name));

rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
const index: string[] = [];
for (const { name, file } of sources) {
  // json-schema-to-zod does not follow $ref, so inline them first.
  const schema = await dereference(JSON.parse(readFileSync(file, "utf8")));
  const code = jsonSchemaToZod(schema, { module: "esm", name, type: true });
  const base = name.replace(/Schema$/, "");
  writeFileSync(
    join(outDir, `${base}.ts`),
    `// Generated by scripts/gen.ts. Do not edit.\n${code}\n`,
  );
  index.push(`export * from "./${base}.ts";`);
}
writeFileSync(
  join(outDir, "index.ts"),
  `// Generated by scripts/gen.ts. Do not edit.\n${index.join("\n")}\n`,
);
console.log(`generated ${sources.length} zod schemas`);
